package main

import (
    "encoding/json"
    "fmt"
    "io"
    "math/rand"
    "os"
    "path/filepath"
    "strings"
    "time"

    tea "github.com/charmbracelet/bubbletea"
    "github.com/charmbracelet/bubbles/progress"
    "github.com/charmbracelet/bubbles/textinput"
    "github.com/charmbracelet/bubbles/viewport"
    "github.com/charmbracelet/lipgloss"
)

// --- CONFIGURATION & ASSETS ---

// Theme definitions for Configurable Themes
type Theme struct {
    Name         string
    Black        lipgloss.Color
    Pink         lipgloss.Color
    MutedPink    lipgloss.Color
    LighterPink  lipgloss.Color
    White        lipgloss.Color
    Error        lipgloss.Color
    Yellow       lipgloss.Color
}

var themes = map[string]Theme{
    "classic": {
        Name:         "Classic Pink",
        Black:        "#000000",
        Pink:         "#FF007F",
        MutedPink:    "#4A0025",
        LighterPink:  "#6A0035",
        White:        "#FFFFFF",
        Error:        "#FF4D4D",
        Yellow:       "#FFFF00",
    },
    "dark": {
        Name:         "Dark Mode",
        Black:        "#000000",
        Pink:         "#A0457E", // Cooler, less saturated pink
        MutedPink:    "#2A1F2E", // Dark purple
        LighterPink:  "#3F2F45",
        White:        "#E0E0E0", // Softer white
        Error:        "#E06C75",
        Yellow:       "#E5C07B",
    },
    "highcontrast": {
        Name:         "High Contrast",
        Black:        "#000000",
        Pink:         "#FF00FF", // Pure magenta
        MutedPink:    "#800080", // Pure purple
        LighterPink:  "#FF00FF",
        White:        "#FFFFFF",
        Error:        "#FF0000", // Pure red
        Yellow:       "#FFFF00",
    },
}

// Session data for persistence
type Session struct {
    Messages []string `json:"messages"`
    History  []string `json:"history"`
}

// --- STYLES (will be dynamically generated) ---
var (
    baseStyle         lipgloss.Style
    glassPanelStyle   lipgloss.Style
    headerStyle       lipgloss.Style
    taglineStyle      lipgloss.Style
    viewportStyle     lipgloss.Style
    userMsgStyle      lipgloss.Style
    floydMsgStyle     lipgloss.Style
    errorStyle        lipgloss.Style
    thinkingStyle     lipgloss.Style
    microInteractionStyle lipgloss.Style
    inputStyle        lipgloss.Style
    statusBarStyle    lipgloss.Style
    helpStyle         lipgloss.Style
)

// generateStyles re-creates all styles based on the current theme
func generateStyles(t Theme) {
    baseStyle = lipgloss.NewStyle().Background(t.Black).Foreground(t.White)
    glassPanelStyle = lipgloss.NewStyle().Background(t.MutedPink).Border(lipgloss.NormalBorder()).BorderForeground(t.Pink).Padding(1)
    headerStyle = glassPanelStyle.Copy().Foreground(t.Pink).Align(lipgloss.Center).BorderTop(false).BorderLeft(false).BorderRight(false)
    taglineStyle = lipgloss.NewStyle().Foreground(t.White).Background(t.MutedPink).Align(lipgloss.Center).MarginTop(1).MarginBottom(1).FontSize(10)
    viewportStyle = glassPanelStyle.Copy().BorderTop(false).BorderBottom(false)
    userMsgStyle = lipgloss.NewStyle().Foreground(t.White).Background(t.LighterPink).Padding(0, 1).MarginBottom(1)
    floydMsgStyle = lipgloss.NewStyle().Foreground(t.White).Padding(0, 1).MarginBottom(1)
    errorStyle = glassPanelStyle.Copy().Foreground(t.Error).BorderForeground(t.Error).Align(lipgloss.Center)
    thinkingStyle = lipgloss.NewStyle().Foreground(t.Yellow).Background(t.MutedPink).Padding(0, 1).MarginBottom(1).Italic(true)
    microInteractionStyle = lipgloss.NewStyle().Foreground(t.Pink).Bold(true)
    inputStyle = lipgloss.NewStyle().Foreground(t.Black).Background(t.White).Padding(0, 1)
    statusBarStyle = glassPanelStyle.Copy().Foreground(t.White).BorderBottom(false).BorderLeft(false).BorderRight(false).Padding(0, 1)
    helpStyle = glassPanelStyle.Copy().Align(lipgloss.Left).BorderForeground(t.Pink)
}

// --- MODEL ---
type model struct {
    viewport           viewport.Model
    input              textinput.Model
    progress           progress.Model
    messages           []string
    history            []string
    historyIndex       int
    ready              bool
    lastError          string
    hasError           bool
    tagline            string
    isThinking         bool
    currentThinking    int
    lastTick           time.Time
    showHelp           bool
    currentTheme       Theme
    sessionPath        string
    progressActive     bool
    progressPercent    float64
}

func initialModel() model {
    rand.Seed(time.Now().UnixNano())
    selectedTagline := taglines[rand.Intn(len(taglines))]

    // Load session and theme
    sessionPath, _ := os.UserHomeDir()
    sessionPath = filepath.Join(sessionPath, ".floyd_session.json")

    // Default to classic theme
    currentTheme := themes["classic"]
    session, _ := loadSession(sessionPath)

    // Generate initial styles
    generateStyles(currentTheme)

    ti := textinput.New()
    ti.Placeholder = "Ask Floyd..."
    ti.Focus()
    ti.CharLimit = 156
    ti.Width = 50
    ti.Prompt = "> "
    ti.PromptStyle = lipgloss.NewStyle().Foreground(currentTheme.Pink)

    vp := viewport.New(0, 0)

    // Progress model setup
    prog := progress.New(progress.WithDefaultGradient(), progress.WithWidth(40), progress.WithoutPercentage())

    return model{
        viewport:        vp,
        input:           ti,
        progress:        prog,
        messages:        session.Messages,
        history:         session.History,
        historyIndex:    len(session.History),
        ready:           false,
        lastError:       "",
        hasError:        false,
        tagline:         selectedTagline,
        isThinking:      false,
        currentThinking: 0,
        lastTick:        time.Now(),
        showHelp:        false,
        currentTheme:    currentTheme,
        sessionPath:     sessionPath,
        progressActive:  false,
        progressPercent: 0.0,
    }
}

// --- INIT ---
func (m model) Init() tea.Cmd {
    return tea.Batch(
        textinput.Blink,
        tea.Tick(time.Second, func(t time.Time) tea.Msg { return tickMsg(t) }),
    )
}

// --- MESSAGES ---
type tickMsg time.Time
type thinkingFinishedMsg struct{ input string }
type progressMsg float64
type saveSessionMsg struct{ session Session }

// --- UPDATE ---
func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
    var (
        cmd  tea.Cmd
        cmds []tea.Cmd
    )

    switch msg := msg.(type) {
    case tea.WindowSizeMsg:
        headerHeight := lipgloss.Height(headerStyle.Render(prismArt)) + lipgloss.Height(taglineStyle.Render(m.tagline))
        statusBarHeight := 1
        inputHeight := 3 // Will need to be dynamic for multi-line
        errorPanelHeight := 0
        if m.hasError {
            errorPanelHeight = lipgloss.Height(m.lastError) + 2
        }
        helpPanelHeight := 0
        if m.showHelp {
            helpPanelHeight = lipgloss.Height(helpContent) + 2
        }

        verticalMargin := headerHeight + statusBarHeight + inputHeight + errorPanelHeight + helpPanelHeight
        if !m.ready {
            m.viewport = viewport.New(msg.Width, msg.Height-verticalMargin)
            m.ready = true
        } else {
            m.viewport.Width = msg.Width - 4
            m.viewport.Height = msg.Height - verticalMargin
        }
        m.input.Width = msg.Width - 6
        m.progress.Width = msg.Width - 10

    case tea.KeyMsg:
        // Handle command input first
        if strings.HasPrefix(m.input.Value(), "/theme ") {
            themeName := strings.TrimPrefix(m.input.Value(), "/theme ")
            if newTheme, ok := themes[themeName]; ok {
                m.currentTheme = newTheme
                generateStyles(m.currentTheme)
                m.input.PromptStyle = lipgloss.NewStyle().Foreground(m.currentTheme.Pink)
                m.messages = append(m.messages, fmt.Sprintf("FLOYD: Theme changed to '%s'.", newTheme.Name))
            } else {
                m.messages = append(m.messages, fmt.Sprintf("FLOYD: Unknown theme '%s'. Available: classic, dark, highcontrast", themeName))
            }
            m.input.Reset()
            m.viewport.GotoBottom()
            return m, nil
        }

        switch msg.Type {
        case tea.KeyEnter:
            if m.input.Value() == "" {
                return m, nil
            }

            userInput := m.input.Value()
            m.history = append(m.history, userInput)
            m.historyIndex = len(m.history)

            userMsg := fmt.Sprintf("USER: %s", userInput)
            m.messages = append(m.messages, userMsg)

            if userInput == "error" {
                m.hasError = true
                m.lastError = "Simulated MCP Error -32000: Connection to the cosmic void failed."
                m.isThinking = false
            } else {
                m.hasError = false
                m.lastError = ""
                m.isThinking = true
                m.currentThinking = rand.Intn(len(thinkingStates))
                state := thinkingStates[m.currentThinking]
                thinkingMsg := fmt.Sprintf("FLOYD: %s %s", state.phrase, state.microInteraction)
                m.messages = append(m.messages, thinkingMsg)

                // Start progress indicator
                m.progressActive = true
                m.progressPercent = 0.0
                cmds = append(cmds, tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg { return progressMsg(0.0) }))

                // Simulate thinking for 3 seconds
                cmds = append(cmds, tea.Tick(3*time.Second, func(t time.Time) tea.Msg {
                    return thinkingFinishedMsg{userInput}
                }))
            }

            m.input.Reset()
            m.viewport.GotoBottom()

        case tea.KeyUp, tea.KeyShiftUp: // Command History
            if m.historyIndex > 0 {
                m.historyIndex--
                m.input.SetValue(m.history[m.historyIndex])
            }
        case tea.KeyDown, tea.KeyShiftDown: // Command History
            if m.historyIndex < len(m.history)-1 {
                m.historyIndex++
                m.input.SetValue(m.history[m.historyIndex])
            } else if m.historyIndex == len(m.history)-1 {
                m.historyIndex++
                m.input.Reset()
            }
        case tea.KeyShiftEnter: // Multi-line Input
            m.input.SetValue(m.input.Value() + "\n")
        case tea.KeyCtrlC, tea.KeyEsc:
            // Save session before quitting
            session := Session{Messages: m.messages, History: m.history}
            return m, tea.Sequence(tea.Quit, func() tea.Msg { return saveSessionMsg{session: session} })
        case tea.KeyQuestion: // Toggle Help
            m.showHelp = !m.showHelp
        }

    case tickMsg:
        m.lastTick = time.Time(msg)
        if m.isThinking {
            if time.Since(m.lastTick).Second()%2 == 0 {
                m.currentThinking = (m.currentThinking + 1) % len(thinkingStates)
            }
            cmds = append(cmds, tea.Tick(time.Second, func(t time.Time) tea.Msg { return tickMsg(t) }))
        }
        return m, tea.Batch(cmds...)

    case thinkingFinishedMsg:
        if len(m.messages) > 0 && m.isThinking {
            m.messages = m.messages[:len(m.messages)-1]
        }
        agentMsg := fmt.Sprintf("FLOYD: I heard you say [%s].", msg.input)
        m.messages = append(m.messages, agentMsg)
        m.isThinking = false
        m.progressActive = false
        m.viewport.GotoBottom()
        cmds = append(cmds, tea.Tick(time.Second, func(t time.Time) tea.Msg { return tickMsg(t) }))

    case progressMsg:
        if m.progressActive {
            m.progressPercent += 0.05
            if m.progressPercent >= 1.0 {
                m.progressPercent = 1.0
                return m, nil // Stop ticking
            }
            cmds = append(cmds, tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg { return progressMsg(m.progressPercent + 0.05) }))
        }

    case saveSessionMsg:
        saveSession(msg.session, m.sessionPath)
    }

    m.input, cmd = m.input.Update(msg)
    cmds = append(cmds, cmd)
    m.viewport, cmd = m.viewport.Update(msg)
    cmds = append(cmds, cmd)

    if m.progressActive {
        m.progress, cmd = m.progress.Update(float64(m.progressPercent))
        cmds = append(cmds, cmd)
    }

    return m, tea.Batch(cmds...)
}

// --- VIEW ---
func (m model) View() string {
    if !m.ready {
        return "\n  Initializing Floyd System..."
    }

    header := headerStyle.Render(prismArt)
    tagline := taglineStyle.Render(m.tagline)

    var errorPanel string
    if m.hasError {
        errorPanel = errorStyle.Render(m.lastError)
    }

    var helpPanel string
    if m.showHelp {
        helpPanel = helpStyle.Render(helpContent)
    }

    var chatHistory strings.Builder
    for i, msg := range m.messages {
        if strings.HasPrefix(msg, "FLOYD: ") && m.isThinking && i == len(m.messages)-1 {
            state := thinkingStates[m.currentThinking]
            thinkingMsg := fmt.Sprintf("FLOYD: %s", state.phrase)
            animation := microInteractionStyle.Render(state.microInteraction)
            chatHistory.WriteString(thinkingStyle.Render(thinkingMsg) + " " + animation + "\n")
        } else if strings.HasPrefix(msg, "USER:") {
            chatHistory.WriteString(userMsgStyle.Render(msg) + "\n")
        } else {
            chatHistory.WriteString(floydMsgStyle.Render(msg) + "\n")
        }
    }
    m.viewport.SetContent(chatHistory.String())
    viewportContent := viewportStyle.Render(m.viewport.View())

    styledInput := inputStyle.Render(m.input.View())

    progressBar := ""
    if m.progressActive {
        progressBar = m.progress.View()
    }

    statusText := fmt.Sprintf("🌌 %s | 💬 %d | ❗ %d | Theme: %s", m.currentTheme.Name, len(m.messages), btoi(m.hasError), m.currentTheme.Name)
    statusBar := statusBarStyle.Render(statusText)

    // Layout assembly
    mainContent := lipgloss.JoinVertical(lipgloss.Left,
        header,
        tagline,
        errorPanel,
        helpPanel,
        viewportContent,
        "", // spacer
        styledInput,
        progressBar,
        statusBar,
    )

    return baseStyle.Render(mainContent)
}

// --- HELPERS ---
func btoi(b bool) int {
    if b { return 1 }
    return 0
}

func loadSession(path string) (Session, error) {
    var s Session
    file, err := os.ReadFile(path)
    if err != nil {
        return s, err
    }
    err = json.Unmarshal(file, &s)
    return s, err
}

func saveSession(s Session, path string) error {
    data, err := json.MarshalIndent(s, "", "  ")
    if err != nil {
        return err
    }
    return os.WriteFile(path, data, 0644)
}

