func (m model) Init() tea.Cmd {
	// Play welcome sound if enabled
	if m.soundEffectsEnabled {
		playSound("welcome")
	}

	return tea.Batch(
		textinput.Blink,
		tea.Tick(time.Second, func(t time.Time) tea.Msg { 
			return tickMsg(t) 
		}),
		tea.EnterAltScreen,
	)
}

// --- MESSAGES ---
type tickMsg time.Time
type thinkingFinishedMsg struct{ input string }
type progressMsg float64
type saveSessionMsg struct{ session Session }
type soundEffectMsg string

// --- UPDATE ---
func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var (
		cmd  tea.Cmd
		cmds []tea.Cmd
	)

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		headerHeight := lipgloss.Height(headerStyle.Render(prismArt)) + lipgloss.Height(taglineStyle.Render(m.tagline))
		statusBarHeight := lipgloss.Height(statusBarStyle.Render("status"))
		inputHeight := lipgloss.Height(m.input.View()) + 1
		errorPanelHeight := 0
		if m.hasError {
			errorPanelHeight = lipgloss.Height(errorStyle.Render(m.lastError)) + 2
		}
		helpPanelHeight := 0
		if m.showHelp {
			helpPanelHeight = lipgloss.Height(helpStyle.Render(helpContent)) + 2
		}

		verticalMargin := headerHeight + statusBarHeight + inputHeight + errorPanelHeight + helpPanelHeight
		if !m.ready {
			m.viewport = viewport.New(msg.Width, msg.Height-verticalMargin)
			m.ready = true
		} else {
			m.viewport.Width = msg.Width - 4
			m.viewport.Height = msg.Height - verticalMargin
		}
		m.input.Width = msg.Width - 6
		m.progress.Width = msg.Width - 10

	case tea.KeyMsg:
		// Handle command input first
		if strings.HasPrefix(m.input.Value(), "/theme ") {
			themeName := strings.TrimPrefix(m.input.Value(), "/theme ")
			if newTheme, ok := themes[themeName]; ok {
				m.currentTheme = newTheme
				generateStyles(m.currentTheme)
				m.input.PromptStyle = lipgloss.NewStyle().Foreground(m.currentTheme.Pink)
				m.messages = append(m.messages, fmt.Sprintf("FLOYD: Theme changed to '%s'. ✨", newTheme.Name))

				// Play theme change sound if enabled
				if m.soundEffectsEnabled {
					playSound("theme_change")
				}
			} else {
				m.messages = append(m.messages, fmt.Sprintf("FLOYD: Unknown theme '%s'. Available: classic, dark, highcontrast", themeName))
			}
			m.input.Reset()
			m.viewport.GotoBottom()
			return m, nil
		}

		switch msg.Type {
		case tea.KeyEnter:
			// Submit on Enter only if the input is on a new, empty line (for multi-line support)
			if m.input.Value() == "" {
				return m, nil
			}

			// Check if we're at the end of a multi-line input with an empty line
			inputVal := m.input.Value()
			if strings.HasSuffix(inputVal, "\n\n") {
				// Submit the message
				userInput := strings.TrimSuffix(inputVal, "\n")
				m.history = append(m.history, userInput)
				m.historyIndex = len(m.history)

				userMsg := fmt.Sprintf("USER: %s [%s]", userInput, time.Now().Format("15:04"))
				m.messages = append(m.messages, userMsg)

				if userInput == "error" {
					m.hasError = true
					m.lastError = "🚨 MCP Error -32000: Connection to the cosmic void failed. Please check your neural pathways."
					m.isThinking = false

					// Play error sound if enabled
					if m.soundEffectsEnabled {
						playSound("error")
					}
				} else {
					m.hasError = false
					m.lastError = ""
					m.isThinking = true
					m.currentThinking = rand.Intn(len(thinkingStates))
					state := thinkingStates[m.currentThinking]
					thinkingMsg := fmt.Sprintf("FLOYD: %s %s [%s]", state.phrase, state.microInteraction, time.Now().Format("15:04"))
					m.messages = append(m.messages, thinkingMsg)

					// Start progress indicator
					m.progressActive = true
					m.progressPercent = 0.0
					cmds = append(cmds, tea.Tick(100*time.Millisecond, func(t time.Time) tea.Msg { 
						return progressMsg(0.0) 
					}))

					// Simulate thinking for 3 seconds
					cmds = append(cmds, tea.Tick(3*time.Second, func(t time.Time) tea.Msg {
						return thinkingFinishedMsg{userInput}
					}))

					// Play thinking sound if enabled
					if m.soundEffectsEnabled {
						playSound("thinking")
					}
				}

				m.input.Reset()
				m.viewport.GotoBottom()
			} else {
				// Add newline for multi-line input
				m.input.SetValue(m.input.Value() + "\n")
			}

		case tea.KeyUp, tea.KeyShiftUp: // Command History
			if len(m.history) > 0 && m.historyIndex > 0 {
				m.historyIndex--
				m.input.SetValue(m.history[m.historyIndex])
			}
		case tea.KeyDown, tea.KeyShiftDown: // Command History
			if m.historyIndex < len(m.history)-1 {
				m.historyIndex++
				m.input.SetValue(m.history[m.historyIndex])
			} else if m.historyIndex == len(m.history)-1 {
				m.historyIndex++
				m.input.Reset()
			}
		case tea.KeyShiftEnter: // Multi-line Input
			m.input.SetValue(m.input.Value() + "\n")
		case tea.KeyCtrlC, tea.KeyEsc:
			// Save session before quitting
			session := Session{Messages: m.messages, History: m.history}
			return m, tea.Sequence(tea.Quit, func() tea.Msg { 
				return saveSessionMsg{session: session} 
			})
		case tea.KeyQuestion: // Toggle Help
			m.showHelp = !m.showHelp
			if m.showHelp {
				// Play help sound if enabled
				if m.soundEffectsEnabled {
					playSound("help")
				}
			}
		case tea.KeyCtrlL: // Clear screen
			m.messages = []string{}
			m.showWelcome = false
		case tea.KeyCtrlT: // Toggle sounds
			m.soundEffectsEnabled = !m.soundEffectsEnabled
			status := "disabled"
			if m.soundEffectsEnabled {
				status = "enabled"
			}
			m.messages = append(m.messages, fmt.Sprintf("FLOYD: Sound effects %s 🎵", status))
		}

	case tickMsg:
		m.lastTick = time.Time(msg)
		m.animationFrame = (m.animationFrame + 1) % 10 // For subtle animations

		if m.isThinking {
			if time.Since(m.lastTick).Milliseconds()%2000 < 1000 {
				m.currentThinking = (m.currentThinking + 1) % len(thinkingStates)
			}
			cmds = append(cmds, tea.Tick(500*time.Millisecond, func(t time.Time) tea.Msg { 
				return tickMsg(t) 
			}))
		}
		return m, tea.Batch(cmds...)

	case thinkingFinishedMsg:
		if len(m.messages) > 0 && m.isThinking {
			// Remove the thinking message
			m.messages = m.messages[:len(m.messages)-1]
		}
		agentMsg := fmt.Sprintf("FLOYD: I processed your request: [%s] 💭 [%s]", 
			highlightStyle.Render(msg.input), 
			time.Now().Format("15:04"))
		m.messages = append(m.messages, agentMsg)
		m.isThinking = false
		m.progressActive = false

		// Play completion sound if enabled
		if m.soundEffectsEnabled {
			playSound("completion")
		}

		m.viewport.GotoBottom()
		cmds = append(cmds, tea.Tick(time.Second, func(t time.Time) tea.Msg { 
			return tickMsg(t) 
		}))

	case progressMsg:
		if m.progressActive {
			m.progressPercent += 0.02
			if m.progressPercent >= 1.0 {
				m.progressPercent = 1.0
				return m, nil // Stop ticking
			}
			cmds = append(cmds, tea.Tick(50*time.Millisecond, func(t time.Time) tea.Msg { 
				return progressMsg(m.progressPercent + 0.02) 
			}))
		}

	case saveSessionMsg:
		saveSession(msg.session, m.sessionPath)
	}

	m.input, cmd = m.input.Update(msg)
	cmds = append(cmds, cmd)
	m.viewport, cmd = m.viewport.Update(msg)
	cmds = append(cmds, cmd)

	if m.progressActive {
		m.progress, cmd = m.progress.Update(m.progressPercent)
		cmds = append(cmds, cmd)
	}

	return m, tea.Batch(cmds...)
}

// --- VIEW ---
func (m model) View() string {
	if !m.ready {
		return "\n  Initializing Floyd System... 🌌"
	}

	header := headerStyle.Render(prismArt)
	tagline := taglineStyle.Render(m.tagline)

	var errorPanel string
	if m.hasError {
		errorPanel = errorStyle.Render(m.lastError)
	}

	var helpPanel string
	if m.showHelp {
		helpPanel = helpStyle.Render(helpContent)
	}

	var welcomePanel string
	if m.showWelcome {
		welcomePanel = welcomeStyle.Render(welcomeMessage)
		m.showWelcome = false // Hide after first display
	}

	var chatHistory strings.Builder

	// Add welcome message if it's the first time
	if len(m.messages) == 0 {
		chatHistory.WriteString(welcomeStyle.Render(welcomeMessage) + "\n\n")
	}

	for i, msg := range m.messages {
		if strings.HasPrefix(msg, "FLOYD: ") && m.isThinking && i == len(m.messages)-1 {
			state := thinkingStates[m.currentThinking]
			thinkingMsg := fmt.Sprintf("FLOYD: %s", state.phrase)
			animation := microInteractionStyle.Render(state.microInteraction)
			chatHistory.WriteString(thinkingStyle.Render(thinkingMsg) + " " + animation + "\n")
		} else if strings.HasPrefix(msg, "USER:") {
			chatHistory.WriteString(userMsgStyle.Render(msg) + "\n")
		} else {
			chatHistory.WriteString(floydMsgStyle.Render(msg) + "\n")
		}
	}

	m.viewport.SetContent(chatHistory.String())
	viewportContent := viewportStyle.Render(m.viewport.View())

	styledInput := inputStyle.Render(m.input.View())

	progressBar := ""
	if m.progressActive {
		progressBar = progressStyle.Render(m.progress.ViewAs(m.progressPercent))
	}

	// Enhanced status bar with more information
	var soundIndicator string
	if m.soundEffectsEnabled {
		soundIndicator = "🔊"
	} else {
		soundIndicator = "🔇"
	}

	statusText := fmt.Sprintf("🌌 %s | 💬 %d | ❗ %d | 🎵 %s | ⌨️ %s", 
		m.currentTheme.Name, 
		len(m.messages), 
		btoi(m.hasError), 
		soundIndicator,
		getCurrentTimeString())
	statusBar := statusBarStyle.Render(statusText)

	// Layout assembly
	mainContent := lipgloss.JoinVertical(lipgloss.Left,
		header,
		tagline,
		welcomePanel,
		errorPanel,
		helpPanel,
		viewportContent,
		"", // spacer
		styledInput,
		progressBar,
		statusBar,
	)

	return baseStyle.Render(mainContent)
}

// --- HELPERS ---
func btoi(b bool) int {
	if b { return 1 }
	return 0
}

func loadSession(path string) (Session, error) {
	var s Session
	file, err := os.ReadFile(path)
	if err != nil {
		// If file doesn't exist, return empty session
		return Session{}, nil
	}
	err = json.Unmarshal(file, &s)
	return s, err
}

func saveSession(s Session, path string) error {
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

