// ===============================
// MODEL
// ===============================
type model struct {
	viewport        viewport.Model
	input           textinput.Model
	progress        progress.Model
	messages        []chatMessage
	history         []string
	historyIndex    int
	ready           bool
	lastError       string
	hasError        bool
	tagline         string
	taglineIndex    int
	isThinking      bool
	executingTools  bool
	currentToolName string
	lastTick        time.Time
	showHelp        bool
	currentTheme    Theme
	themeName       string
	sessionPath     string
	progressActive  bool
	progressPercent float64
	animationFrame  int
	elapsedTime     time.Duration

	// Agent integration
	client           *agent.ProxyClient
	loopAgent        *loop.LoopAgent
	toolExecutor     *agenttools.Executor
	protocolMgr      *floyd.ProtocolManager
	safety           *floyd.SafetyEnforcer
	conversation     []agent.Message

	// Streaming state
	streamCancel     context.CancelFunc
	pendingTokens    []string
	currentResponse  strings.Builder

	mu               sync.Mutex
}

type chatMessage struct {
	role      string  // "user", "assistant", "system", "tool"
	content   string
	toolName  string
	isError   bool
}

func initialModel() model {
	rand.Seed(time.Now().UnixNano())

	sessionPath, _ := os.UserHomeDir()
	sessionPath = filepath.Join(sessionPath, ".floyd_session.json")

	session, _ := loadSession(sessionPath)

	themeName := session.Theme
	if themeName == "" {
		themeName = "classic"
	}
	currentTheme := themes[themeName]
	generateStyles(currentTheme)

	taglineIndex := session.LastTagline
	taglinesCount := len(taglines)
	if taglineIndex >= taglinesCount {
		taglineIndex = 0
	}
	selectedTagline := taglines[taglineIndex]

	ti := textinput.New()
	ti.Placeholder = "Ask FLOYD..."
	ti.Focus()
	ti.CharLimit = 500
	ti.Width = 50
	ti.Prompt = "> "
	ti.PromptStyle = lipgloss.NewStyle().Foreground(currentTheme.Pink)

	vp := viewport.New(0, 0)

	prog := progress.New(
		progress.WithDefaultGradient(),
		progress.WithWidth(40),
		progress.WithoutPercentage(),
	)

	// Initialize agent components
	client := createAgentClient()
	if client == nil {
		// Will show error in UI
		return model{
			viewport:       vp,
			input:          ti,
			progress:       prog,
			messages:       []chatMessage{{role: "system", content: "❌ Error: No API key found. Set ANTHROPIC_AUTH_TOKEN or GLM_API_KEY."}},
			ready:          true,
			currentTheme:   currentTheme,
			themeName:      themeName,
			sessionPath:    sessionPath,
		}
	}

	executor := agenttools.NewExecutor(30 * time.Second)
	protocolMgr := floyd.NewProtocolManager(".floyd")
	safety := floyd.NewSafetyEnforcer()
	loopAgent := loop.NewLoopAgent(client, executor)

	return model{
		viewport:        vp,
		input:           ti,
		progress:        prog,
		messages:        sessionToMessages(session),
		history:         session.History,
		historyIndex:    len(session.History),
		ready:           false,
		lastError:       "",
		hasError:        false,
		tagline:         selectedTagline,
		taglineIndex:    taglineIndex,
		isThinking:      false,
		executingTools:   false,
		lastTick:         time.Now(),
		showHelp:         false,
		currentTheme:     currentTheme,
		themeName:        themeName,
		sessionPath:      sessionPath,
		progressActive:   false,
		progressPercent:  0.0,
		animationFrame:   0,
		elapsedTime:      0,
		pendingTokens:    make([]string, 0, 50),
		conversation:      make([]agent.Message, 0),
		client:           client,
		loopAgent:        loopAgent,
		toolExecutor:     executor,
		protocolMgr:       protocolMgr,
		safety:           safety,
	}
}

func sessionToMessages(s Session) []chatMessage {
	msgs := make([]chatMessage, len(s.Messages))
	for i, m := range s.Messages {
		msgs[i] = chatMessage{role: "assistant", content: m}
	}
	return msgs
}

func messagesToSession(msgs []chatMessage) Session {
	strs := make([]string, len(msgs))
	for i, m := range msgs {
		strs[i] = m.content
	}
	return Session{
		Messages: strs,
	}
}

// ===============================
// INIT
// ===============================
func (m model) Init() tea.Cmd {
	if len(m.messages) == 0 || (len(m.messages) == 1 && strings.Contains(m.messages[0].content, "Error:")) {
		if m.client == nil {
			return tea.Quit
		}
		m.messages = append(m.messages, chatMessage{
			role:    "system",
			content: "✅ FLOYD initialized with GLM-4.7. Tools armed. Protocol loaded.",
		})
	}

	return tea.Batch(
		textinput.Blink,
		tea.Tick(time.Millisecond*50, func(t time.Time) tea.Msg {
			return tickMsg(t)
		}),
	)
}

// ===============================
// MESSAGES
// ===============================
type tickMsg time.Time
type thinkingFinishedMsg struct{ response string }
type progressMsg float64
type saveSessionMsg struct{ session Session }
type agentResponseMsg struct{ response string }
type toolUseMsg struct{ toolName string }
type toolResultMsg struct{ toolName, content string }

// ===============================
// UPDATE
// ===============================
func (m model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var (
		cmd  tea.Cmd
		cmds []tea.Cmd
	)

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		headerHeight := lipgloss.Height(headerStyle.Render(prismArt))
		taglineHeight := lipgloss.Height(taglineStyle.Render(m.tagline))
		statusBarHeight := 1

		inputLines := strings.Count(m.input.Value(), "\n") + 1
		inputHeight := inputLines + 2

		errorPanelHeight := 0
		if m.hasError {
			errorPanelHeight = lipgloss.Height(m.lastError) + 2
		}
		helpPanelHeight := 0
		if m.showHelp {
			helpPanelHeight = lipgloss.Height(helpContent) + 2
		}

		verticalMargin := headerHeight + taglineHeight + statusBarHeight + inputHeight + errorPanelHeight + helpPanelHeight + 2

		if !m.ready {
			m.viewport = viewport.New(msg.Width, msg.Height-verticalMargin)
			m.ready = true
		} else {
			m.viewport.Width = msg.Width - 4
			m.viewport.Height = msg.Height - verticalMargin
		}
		m.input.Width = msg.Width - 6
		m.progress.Width = msg.Width - 10

	case tea.KeyMsg:
		if strings.HasPrefix(m.input.Value(), "/") {
			return m.handleCommand(msg)
		}

		switch msg.Type {
		case tea.KeyEnter:
			if m.input.Value() == "" {
				return m, nil
			}

			if m.isThinking || m.executingTools {
				return m, nil
			}

			userInput := strings.TrimSpace(m.input.Value())
			if userInput == "" {
				return m, nil
			}

			// Check safety rules before executing
			if err := m.safety.CheckAction(userInput); err != nil {
				m.messages = append(m.messages, chatMessage{
					role:    "system",
					content: fmt.Sprintf("🚫 SAFETY: %v", err),
				})
				m.input.Reset()
				m.updateViewport()
				return m, nil
			}

			m.history = append(m.history, userInput)
			m.historyIndex = len(m.history)

			m.messages = append(m.messages, chatMessage{role: "user", content: userInput})

			m.input.Reset()
			m.isThinking = true
			m.animationFrame = 0
			m.elapsedTime = 0
			m.progressActive = true
			m.progressPercent = 0.0

			// Start agent request
			cmds = append(cmds, m.callAgent(userInput))
			cmds = append(cmds, tea.Tick(time.Millisecond*100, func(t time.Time) tea.Msg {
				return progressMsg(0.05)
			}))

		case tea.KeyUp, tea.KeyShiftUp:
			if m.historyIndex > 0 {
				m.historyIndex--
				m.input.SetValue(m.history[m.historyIndex])
			}
		case tea.KeyDown, tea.KeyShiftDown:
			if m.historyIndex < len(m.history)-1 {
				m.historyIndex++
				m.input.SetValue(m.history[m.historyIndex])
			} else if m.historyIndex == len(m.history)-1 {
				m.historyIndex++
				m.input.Reset()
			}
		case tea.KeyCtrlC, tea.KeyEsc:
			session := Session{
				Messages:    messagesToSession(m.messages),
				History:     m.history,
				Theme:       m.themeName,
				LastTagline: (m.taglineIndex + 1) % len(taglines),
			}
			return m, tea.Sequence(tea.Quit, func() tea.Msg {
				return saveSessionMsg{session: session}
			})
		}
		if msg.String() == "?" {
			m.showHelp = !m.showHelp
		}

	case tickMsg:
		m.lastTick = time.Time(msg)
		m.elapsedTime += 50 * time.Millisecond
		m.animationFrame = (m.animationFrame + 1) % 20
		cmds = append(cmds, tea.Tick(time.Millisecond*50, func(t time.Time) tea.Msg {
			return tickMsg(t)
		}))

	case thinkingFinishedMsg:
		m.isThinking = false
		m.executingTools = false
		m.progressActive = false

		m.messages = append(m.messages, chatMessage{role: "assistant", content: msg.response})

		// Log to progress
		m.protocolMgr.LogAction("chat", "completed", "ready")
		m.updateViewport()

	case toolUseMsg:
		m.executingTools = true
		m.currentToolName = msg.toolName
		m.messages = append(m.messages, chatMessage{role: "tool", content: fmt.Sprintf("▶ Using: %s", msg.toolName)})
		m.updateViewport()

	case toolResultMsg:
		m.executingTools = false
		m.messages = append(m.messages, chatMessage{role: "tool_result", toolName: msg.toolName, content: msg.content})
		m.updateViewport()

	case progressMsg:
		if m.progressActive {
			m.progressPercent += msg.progress
			if m.progressPercent >= 1.0 {
				m.progressPercent = 1.0
			}
			m.progress, cmd = m.progress.Update(m.progressPercent)
			cmds = append(cmds, cmd)
		}

	case saveSessionMsg:
		saveSession(msg.session, m.sessionPath)
	}

	m.input, cmd = m.input.Update(msg)
	cmds = append(cmds, cmd)
	m.viewport, cmd = m.viewport.Update(msg)
	cmds = append(cmds, cmd)

	return m, tea.Batch(cmds...)
}

func (m *model) callAgent(userInput string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
		m.streamCancel = cancel

		m.mu.Lock()
		m.conversation = append(m.conversation, agent.Message{Role: "user", Content: userInput})
		m.mu.Unlock()

		// Build request with protocol
		req := agent.ChatRequest{
			Messages:    m.conversation,
			MaxTokens:   4096,
			Temperature: 0.7,
		}
		req = m.protocolMgr.EnhancedChatRequest(req, "")

		// Run tool loop
		response, err := m.loopAgent.RunToolLoop(ctx, req)
		if err != nil {
			return thinkingFinishedMsg{response: fmt.Sprintf("Error: %v", err)}
		}

		// Update conversation
		m.mu.Lock()
		m.conversation = append(m.conversation, agent.Message{Role: "assistant", Content: response})
		m.mu.Unlock()

		return thinkingFinishedMsg{response: response}
	}
}

func (m *model) updateViewport() {
	var chatHistory strings.Builder

	for _, msg := range m.messages {
		var styled string
		switch msg.role {
		case "user":
			styled = userMsgStyle.Render("YOU: " + msg.content)
		case "assistant":
			styled = floydMsgStyle.Render("FLOYD: " + msg.content)
		case "tool":
			styled = toolUseStyle.Render(msg.content)
		case "tool_result":
			styled = toolUseStyle.Render("✓ " + msg.toolName + ": " + truncate(msg.content, 100))
		case "system":
			if strings.Contains(msg.content, "🚫") {
				styled = errorStyle.Render(msg.content)
			} else if strings.Contains(msg.content, "✅") {
				styled = floydMsgStyle.Copy().Foreground(m.currentTheme.Green).Render(msg.content)
			} else {
				styled = thinkingStyle.Render(msg.content)
			}
		}
		chatHistory.WriteString(styled + "\n")
	}

	m.viewport.SetContent(chatHistory.String())
	m.viewport.GotoBottom()
}

func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen-3] + "..."
}

// ===============================
// COMMANDS
// ===============================
func (m model) handleCommand(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if msg.Type != tea.KeyEnter {
		m.input, _ = m.input.Update(msg)
		return m, nil
	}

	input := strings.TrimSpace(m.input.Value())
	cmd := strings.TrimPrefix(input, "/")
	parts := strings.Fields(cmd)
	if len(parts) == 0 {
		return m, nil
	}

	switch strings.ToLower(parts[0]) {
	case "theme":
		if len(parts) < 2 {
			m.messages = append(m.messages, chatMessage{
				role: "system",
				content: "Available themes: classic, dark, highcontrast, cyberpunk, midnight",
			})
			m.input.Reset()
			m.updateViewport()
			return m, nil
		}
		themeName := strings.ToLower(parts[1])
		if newTheme, ok := themes[themeName]; ok {
			m.currentTheme = newTheme
			m.themeName = themeName
			generateStyles(m.currentTheme)
			m.input.PromptStyle = lipgloss.NewStyle().Foreground(m.currentTheme.Pink)
			m.messages = append(m.messages, chatMessage{
				role:    "system",
				content: fmt.Sprintf("Theme changed to '%s'.", newTheme.Name),
			})
		} else {
			m.messages = append(m.messages, chatMessage{
				role: "system",
				content: fmt.Sprintf("Unknown theme '%s'. Available: classic, dark, highcontrast, cyberpunk, midnight", themeName),
			})
		}
		m.input.Reset()
		m.updateViewport()
		return m, nil

	case "clear", "cls":
		m.messages = []chatMessage{}
		m.conversation = []agent.Message{}
		m.input.Reset()
		m.updateViewport()
		return m, nil

	case "help", "h", "?":
		m.showHelp = !m.showHelp
		m.input.Reset()
		m.updateViewport()
		return m, nil

	case "status":
		status := m.protocolMgr.WorkspaceStatus()
		var sb strings.Builder
		sb.WriteString("📁 Workspace Status:\n")
		for k, v := range status {
			sb.WriteString(fmt.Sprintf("  %s: %s\n", k, v))
		}
		m.messages = append(m.messages, chatMessage{role: "system", content: sb.String()})
		m.input.Reset()
		m.updateViewport()
		return m, nil

	case "tools":
		tools := agenttools.ListTools()
		m.messages = append(m.messages, chatMessage{
			role:    "system",
			content: fmt.Sprintf("Available Tools (%d): %s", len(tools), strings.Join(tools, ", ")),
		})
		m.input.Reset()
		m.updateViewport()
		return m, nil

	case "init":
		if err := prompt.InitializeFloydDir(); err != nil {
			m.messages = append(m.messages, chatMessage{
				role:    "system",
				content: fmt.Sprintf("Init failed: %v", err),
			})
		} else {
			m.messages = append(m.messages, chatMessage{
				role:    "system",
				content: "✅ .floyd/ workspace initialized",
			})
		}
		m.input.Reset()
		m.updateViewport()
		return m, nil
	}

	return m, nil
}

// ===============================
// VIEW
// ===============================
func (m model) View() string {
	if !m.ready {
		return "\n  Initializing FLOYD..."
	}

	header := headerStyle.Render(prismArt)
	tagline := taglineStyle.Render("「 " + m.tagline + " 」")

	var errorPanel string
	if m.hasError {
		errorPanel = "\n" + errorStyle.Render("⚠ " + m.lastError)
	}

	var helpPanel string
	if m.showHelp {
		helpPanel = "\n" + helpStyle.Render(helpContent)
	}

	var chatHistory strings.Builder
	for _, msg := range m.messages {
		var styled string
		switch {
		case msg.role == "user":
			styled = userMsgStyle.Render("YOU: " + msg.content)
		case msg.role == "assistant":
			styled = floydMsgStyle.Render("FLOYD: " + msg.content)
		case msg.role == "tool":
			styled = toolUseStyle.Render(msg.content)
		case msg.role == "tool_result":
			styled = toolUseStyle.Render("✓ " + msg.toolName + ": " + truncate(msg.content, 150))
		default:
			if strings.Contains(msg.content, "🚫") {
				styled = errorStyle.Render(msg.content)
			} else if strings.Contains(msg.content, "✅") {
				styled = floydMsgStyle.Copy().Foreground(m.currentTheme.Green).Render(msg.content)
			} else {
				styled = thinkingStyle.Render(msg.content)
			}
		}
		chatHistory.WriteString(styled + "\n")
	}

	// Show thinking animation
	if m.isThinking {
		phrase := spinners.GetPhrase(m.animationFrame % spinners.PhraseCount())
		frame := spinners.GetFrame(phrase.SpinIndex, m.elapsedTime)
		thinkingMsg := fmt.Sprintf("FLOYD: %s", phrase.Phrase)
		chatHistory.WriteString(thinkingStyle.Render(thinkingMsg) + " " + frame + "\n")
	}

	m.viewport.SetContent(chatHistory.String())
	viewportContent := viewportStyle.Render(m.viewport.View())

	inputLines := strings.Split(m.input.View(), "\n")
	inputContent := strings.Join(inputLines, "\n")
	inputPanelHeight := len(inputLines) + 2
	styledInput := inputStyle.Height(inputPanelHeight).Width(m.viewport.Width).Render(inputContent)

	progressBar := ""
	if m.progressActive {
		progressBar = "\n" + m.progress.View()
	}

	statusText := "● READY"
	if m.isThinking {
		statusText = "❯ THINKING"
	} else if m.executingTools {
		statusText = "▶ TOOLS: " + m.currentToolName
	}
	statusText = fmt.Sprintf(" %s │ 💬 %d │ %s │ Theme: %s ",
		statusText,
		len(m.messages),
		map[bool]string{true: "❯ THINKING", false: "● READY"}[m.isThinking || m.executingTools],
		m.themeName,
	)
	statusBar := statusBarStyle.Render(statusText)

	mainContent := lipgloss.JoinVertical(lipgloss.Left,
		header,
		tagline,
		errorPanel,
		helpPanel,
		viewportContent,
		"",
		styledInput,
		progressBar,
		statusBar,
	)

	return baseStyle.Render(mainContent)
}

func loadSession(path string) (Session, error) {
	var s Session
	file, err := os.ReadFile(path)
	if err != nil {
		return s, err
	}
	err = json.Unmarshal(file, &s)
	return s, err
}

func saveSession(s Session, path string) error {
	data, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

func createAgentClient() *agent.ProxyClient {
	apiKey := os.Getenv("ANTHROPIC_AUTH_TOKEN")
	if apiKey == "" {
		apiKey = os.Getenv("GLM_API_KEY")
	}
	if apiKey == "" {
		apiKey = os.Getenv("ZHIPU_API_KEY")
	}
	if apiKey == "" {
		homeDir, _ := os.UserHomeDir()
		data, _ := os.ReadFile(filepath.Join(homeDir, ".claude/settings.json"))
		var settings struct {
			Env struct {
				AnthropicAuthToken string `json:"ANTHROPIC_AUTH_TOKEN"`
			} `json:"env"`
		}
		if data != nil && json.Unmarshal(data, &settings) == nil {
			apiKey = settings.Env.AnthropicAuthToken
		}
	}

	if apiKey == "" {
		return nil
	}

	client := agent.NewProxyClient(apiKey, "https://api.z.ai/api/anthropic")
	client.SetModel("claude-opus-4")
	return client
}

